package workbench.bytecode.l04;

import java.lang.reflect.InvocationHandler;
import java.lang.reflect.Modifier;
import java.lang.reflect.Proxy;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

/** What Proxy.newProxyInstance generates, which calls reach the handler, and how the class is cached. */
public class ProxyAnatomy {
    public interface FxQuotes {
        long quoteMicros(String pair);
        default long spreadMicros(String pair) { return quoteMicros(pair) / 1_000; }
    }

    public interface Audited { String auditId(); }

    public static void main(String[] args) {
        List<String> seen = new ArrayList<>();
        InvocationHandler h = (proxy, m, a) -> {
            seen.add(m.getDeclaringClass().getSimpleName() + "." + m.getName());
            return switch (m.getName()) {
                case "quoteMicros" -> 1_084_250L;
                case "hashCode" -> 42;
                case "equals" -> proxy == a[0];
                case "toString" -> "FxQuotes proxy";
                default -> null;
            };
        };
        ClassLoader app = FxQuotes.class.getClassLoader();
        FxQuotes q = (FxQuotes) Proxy.newProxyInstance(app, new Class<?>[]{FxQuotes.class}, h);

        // 1. the generated class
        Class<?> pc = q.getClass();
        System.out.println("class      " + Modifier.toString(pc.getModifiers()) + " " + pc.getName());
        System.out.println("extends    " + pc.getSuperclass().getName() + ", implements " + Arrays.toString(pc.getInterfaces()));
        System.out.println("module     " + pc.getModule().getName() + ", hidden: " + pc.isHidden());
        System.out.println("fields     " + Arrays.stream(pc.getDeclaredFields()).map(f -> f.getName()).sorted().toList());
        System.out.println("methods    " + Arrays.stream(pc.getDeclaredMethods()).map(m -> m.getName()).sorted().toList());

        // 2. which calls reach the handler
        q.quoteMicros("EURUSD");
        q.toString();
        q.hashCode();
        q.equals(q);
        q.getClass();
        System.out.println("handler saw " + seen);

        // 3. the class is cached per loader and per ordered interface list
        Object again = Proxy.newProxyInstance(app, new Class<?>[]{FxQuotes.class}, (p, m, a) -> 0L);
        Object ab = Proxy.newProxyInstance(app, new Class<?>[]{FxQuotes.class, Audited.class}, h);
        Object ba = Proxy.newProxyInstance(app, new Class<?>[]{Audited.class, FxQuotes.class}, h);
        System.out.println("same class for the same interface: " + (again.getClass() == pc));
        System.out.println("{FxQuotes, Audited} -> " + ab.getClass().getName() + ", {Audited, FxQuotes} -> " + ba.getClass().getName());
    }
}

package workbench.bytecode.l04;

import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Proxy;
import java.lang.reflect.UndeclaredThrowableException;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/** Two handler bugs: forwarding equals to the target, and throwing a checked exception the method doesn't declare. */
public class ObjectMethodsDemo {
    public interface IssuerClient {
        String authorize(String pan) throws IOException;   // declares IOException
        String status();                                   // declares nothing
    }

    static class RealIssuer implements IssuerClient {
        public String authorize(String pan) throws IOException { throw new IOException("issuer timed out after 120 ms"); }
        public String status() { return "UP"; }
    }

    static IssuerClient forwardingEverything(IssuerClient target) {
        return (IssuerClient) Proxy.newProxyInstance(IssuerClient.class.getClassLoader(), new Class<?>[]{IssuerClient.class},
                (proxy, m, args) -> {
                    try {
                        return m.invoke(target, args);   // equals and hashCode go to the target too
                    } catch (InvocationTargetException e) {
                        throw e.getCause();
                    }
                });
    }

    public static void main(String[] args) {
        IssuerClient p = forwardingEverything(new RealIssuer());
        System.out.println("p.equals(p): " + p.equals(p) + "   (target.equals(p) was asked)");
        List<IssuerClient> listeners = new ArrayList<>();
        listeners.add(p);
        System.out.println("listeners.remove(p) after listeners.add(p): " + listeners.remove(p) + ", size still " + listeners.size());
        Set<IssuerClient> set = new HashSet<>(listeners);
        System.out.println("HashSet.contains(p): " + set.contains(p) + "   (HashMap checks == before equals)");

        try {
            p.authorize("4111111111111111");
        } catch (IOException e) {
            System.out.println("declared IOException passes through: " + e.getMessage());
        }

        IssuerClient angry = (IssuerClient) Proxy.newProxyInstance(IssuerClient.class.getClassLoader(),
                new Class<?>[]{IssuerClient.class}, (proxy, m, a) -> { throw new IOException("connection reset"); });
        try {
            angry.status();
        } catch (UndeclaredThrowableException e) {
            System.out.println("undeclared IOException from status() -> UndeclaredThrowableException, cause: " + e.getCause());
        }
    }
}

