@SuppressWarnings("unchecked")
static <T> T tracing(Class<T> iface, T target, List<String> log) {
    InvocationHandler h = (proxy, m, args) -> {
        if (m.getDeclaringClass() == Object.class) {          // 1. identity, not the target's
            return switch (m.getName()) {
                case "equals" -> proxy == args[0];
                case "hashCode" -> System.identityHashCode(proxy);
                default -> "Tracing[" + target + "]";
            };
        }
        log.add(m.getName());
        if (m.isDefault()) return InvocationHandler.invokeDefault(proxy, m, args);  // 2. this = proxy
        try {
            return m.invoke(target, args);                    // 3. args is null for no-arg methods
        } catch (InvocationTargetException e) {
            throw e.getCause();                               // 4. the target's own exception
        }
    };
    return (T) Proxy.newProxyInstance(iface.getClassLoader(), new Class<?>[]{iface}, h);
}

kotlin.src:
inline fun <reified T : Any> tracing(target: T, log: MutableList<String>): T =
    Proxy.newProxyInstance(T::class.java.classLoader, arrayOf(T::class.java)) { proxy, m, args ->
        val a = args ?: emptyArray()                          // 3. null for no-arg methods
        when {
            m.declaringClass == Any::class.java -> when (m.name) {   // 1. identity
                "equals" -> proxy === a[0]
                "hashCode" -> System.identityHashCode(proxy)
                else -> "Tracing[$target]"
            }
            else -> {
                log += m.name
                if (m.isDefault) InvocationHandler.invokeDefault(proxy, m, *a)   // 2. this = proxy
                else try {
                    m.invoke(target, *a)
                } catch (e: InvocationTargetException) {
                    throw e.cause!!                           // 4. the target's own exception
                }
            }
        }
    } as T

