static CardIssuerClient fakeIssuer(Map<String, Object> answers, List<String> calls) {
    InvocationHandler h = (proxy, m, args) -> {
        // 1. Object methods: identity, so the fake behaves in collections
        if (m.getDeclaringClass() == Object.class) {
            return switch (m.getName()) {
                case "equals" -> proxy == args[0];
                case "hashCode" -> System.identityHashCode(proxy);
                default -> "FakeIssuer" + answers.keySet();
            };
        }
        // 2. default methods: run the real interface body, which calls back through this handler
        if (m.isDefault()) return InvocationHandler.invokeDefault(proxy, m, args);
        // 3. abstract methods: record the call and return the canned answer
        calls.add(m.getName() + Arrays.toString(args));
        if (!answers.containsKey(m.getName())) throw new UnsupportedOperationException(m.getName());
        return answers.get(m.getName());
    };
    return (CardIssuerClient) Proxy.newProxyInstance(
            CardIssuerClient.class.getClassLoader(), new Class<?>[]{CardIssuerClient.class}, h);
}

