    if (m.getDeclaringClass() == Object.class) {                        // 1. Object methods
        return switch (m.getName()) {
            case "equals" -> proxy == args[0];
            case "hashCode" -> System.identityHashCode(proxy);
            default -> "Timed[" + target + "]";
        };
    }
    if (m.isDefault()) return InvocationHandler.invokeDefault(proxy, m, args);  // 2. defaults: this = proxy
    long t0 = System.nanoTime();
    try {
        return m.invoke(target, args);                                  // 3. the timed call
    } catch (InvocationTargetException e) {
        throw e.getCause();                                             // 4. unwrap
    } finally {
        metrics.record(m.getName(), System.nanoTime() - t0);
    }
};

